#include <vector>
#include <cmath>
#include <stdexcept>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("b size must be N");
    }

    x.assign(N, 0.0);

    // Build CSR from COO safely (sequential build for correctness/simplicity).
    std::vector<size_t> rowCount(N, 0);
    for (const auto& e : A) {
        if (e.row >= N || e.column >= N) {
            throw std::out_of_range("COO element index out of range");
        }
        rowCount[e.row]++;
    }

    std::vector<size_t> rowPtr(N + 1, 0);
    for (size_t i = 0; i < N; ++i) {
        rowPtr[i + 1] = rowPtr[i] + rowCount[i];
    }

    std::vector<size_t> colIdx(A.size());
    std::vector<double> vals(A.size());
    std::vector<size_t> nextPos = rowPtr;
    for (const auto& e : A) {
        size_t p = nextPos[e.row]++;
        colIdx[p] = e.column;
        vals[p] = e.value;
    }

    // Jacobi iteration: thread-safe for any thread count.
    std::vector<double> xNew(N, 0.0);
    const size_t maxIters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        // Compute new iterate in parallel.
        #pragma omp parallel for schedule(static)
        for (ptrdiff_t i = 0; i < static_cast<ptrdiff_t>(N); ++i) {
            double diag = 0.0;
            double sum = 0.0;

            for (size_t p = rowPtr[static_cast<size_t>(i)]; p < rowPtr[static_cast<size_t>(i) + 1]; ++p) {
                size_t j = colIdx[p];
                double aij = vals[p];
                if (j == static_cast<size_t>(i)) {
                    diag += aij; // handle duplicate diagonal entries
                } else {
                    sum += aij * x[j];
                }
            }

            if (std::abs(diag) > 0.0) {
                xNew[static_cast<size_t>(i)] = (b[static_cast<size_t>(i)] - sum) / diag;
            } else {
                // If no usable diagonal, keep previous value.
                xNew[static_cast<size_t>(i)] = x[static_cast<size_t>(i)];
            }
        }

        // Compute convergence metric with reduction.
        double maxDiff = 0.0;
        #pragma omp parallel for reduction(max:maxDiff) schedule(static)
        for (ptrdiff_t i = 0; i < static_cast<ptrdiff_t>(N); ++i) {
            double d = std::abs(xNew[static_cast<size_t>(i)] - x[static_cast<size_t>(i)]);
            if (d > maxDiff) maxDiff = d;
        }

        x.swap(xNew);

        if (maxDiff < tol) {
            break;
        }
    }
}
